import React from 'react';
import { useNavigate } from 'react-router-dom';
import { logout } from '../services/api'; // Ensure the path is correct
import ExamDataUser from './ExamDataUser';

const UserDashboard = () => {
  const navigate = useNavigate();

  // Handle logout logic
  const handleLogout = async () => {
    try {
      const message = await logout();
      console.log(message); // Optional: Display the success message

      // Clear the token from localStorage
      localStorage.removeItem('token');

      // Navigate to the login page
      navigate('/login');
    } catch (error) {
      console.error('Logout failed:', error);
      alert('There was an error logging out. Please try again.');
    }
  };

  return (
    <div>
      <h1>User Dashboard</h1>
      <button onClick={() => navigate('/exam-data-user')}>Manage Exam Data</button>

      {/* Logout button */}
      <button onClick={handleLogout}>Logout</button>
      <ExamDataUser/>
    </div>
  );
};

export default UserDashboard;
